 with zipfile.ZipFile(b,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=9) as z:
  for name,value in sorted(files.items()):
   if name.startswith('/') or '..' in Path(name).parts:raise ValueError('Unsafe bundle member')
   data=value.encode() if isinstance(value,str) else value;safe_check(data.decode('utf8'));info=zipfile.ZipInfo(name,date_time=(2026,10,4,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o644<<16;z.writestr(info,data)
 return b.getvalue()
